import { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';
import crypto from 'crypto';
import { RedisClient } from '../cache/redis_client';
import { SecurityLogger } from '../utils/logger';

export interface UserTokenPayload {
  userId: string;
  tenantId: string;
  roles: string[];
  scopes: string[];
  iat: number;
  exp: number;
  iss: string;
}

export class AuthManager {
  private redisClient: RedisClient;
  private publicKeyPEM: string;
  private keyRotationTTL: number = 86400;

  constructor(redisClient: RedisClient, publicKeyPEM: string) {
    this.redisClient = redisClient;
    this.publicKeyPEM = publicKeyPEM;
  }

  public async authenticateRequest(req: Request, res: Response, next: NextFunction): Promise<void> {
    try {
      const authHeader = req.headers.authorization;
      if (!authHeader || !authHeader.startsWith('Bearer ')) {
        res.status(401).json({ error: 'Missing or malformed Authorization header' });
        return;
      }

      const token = authHeader.split(' ')[1];
      const decoded = jwt.verify(token, this.publicKeyPEM, { algorithms: ['RS256'] }) as UserTokenPayload;

      const isBlacklisted = await this.redisClient.get(`token:blacklisted:${token}`);
      if (isBlacklisted) {
        SecurityLogger.warn(`Blacklisted token attempt detected for user: ${decoded.userId}`);
        res.status(403).json({ error: 'Token revoked' });
        return;
      }

      (req as any).user = decoded;
      next();
    } catch (err: any) {
      SecurityLogger.error(`JWT Verification failure: ${err.message}`);
      res.status(401).json({ error: 'Invalid or expired authentication token' });
    }
  }

  public async revokeToken(token: string, ttlSeconds: number): Promise<void> {
    await this.redisClient.setEx(`token:blacklisted:${token}`, ttlSeconds, 'true');
  }
}

import { PoolClient } from 'pg';
import { RedisClient } from '../cache/redis_client';
import { KafkaProducer } from '../events/kafka_producer';
import { MetricsCollector } from '../monitoring/metrics';

export interface OrderItem {
  sku: string;
  quantity: number;
  unitPrice: number;
  warehouseId: string;
}

export interface OrderPayload {
  orderId: string;
  customerId: string;
  tenantId: string;
  items: OrderItem[];
  paymentMethodId: string;
  shippingAddress: string;
  idempotencyKey: string;
}

export class OrderProcessor {
  private dbPool: any;
  private redisClient: RedisClient;
  private kafkaProducer: KafkaProducer;

  constructor(dbPool: any, redisClient: RedisClient, kafkaProducer: KafkaProducer) {
    this.dbPool = dbPool;
    this.redisClient = redisClient;
    this.kafkaProducer = kafkaProducer;
  }

  public async processOrder(order: OrderPayload): Promise<{ success: boolean; transactionId?: string; error?: string }> {
    const startTime = Date.now();
    const client: PoolClient = await this.dbPool.connect();

    try {
      // Check Idempotency Key in Redis
      const existingTx = await this.redisClient.get(`idempotency:order:${order.idempotencyKey}`);
      if (existingTx) {
        return { success: true, transactionId: existingTx };
      }

      await client.query('BEGIN ISOLATION LEVEL SERIALIZABLE');

      // Verify Inventory Stock with DB Locks
      for (const item of order.items) {
        const stockRes = await client.query('SELECT stock_quantity FROM inventory WHERE sku = $1 FOR UPDATE', [item.sku]);
        if (stockRes.rows.length === 0 || stockRes.rows[0].stock_quantity < item.quantity) {
          await client.query('ROLLBACK');
          MetricsCollector.increment('order_failure_insufficient_stock');
          return { success: false, error: `Insufficient stock for SKU: ${item.sku}` };
        }
      }

      // Deduct Inventory Stock
      for (const item of order.items) {
        await client.query('UPDATE inventory SET stock_quantity = stock_quantity - $1 WHERE sku = $2', [item.quantity, item.sku]);
      }

      // Compute Total Amount
      const totalAmount = order.items.reduce((sum, item) => sum + (item.quantity * item.unitPrice), 0);
      const transactionId = `txn_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

      // Record Order DB Entry
      await client.query(
        'INSERT INTO orders (id, customer_id, tenant_id, total_amount, status, transaction_id, created_at) VALUES ($1, $2, $3, $4, $5, $6, NOW())',
        [order.orderId, order.customerId, order.tenantId, totalAmount, 'CONFIRMED', transactionId]
      );

      await client.query('COMMIT');

      // Cache Idempotency Lock for 24h
      await this.redisClient.setEx(`idempotency:order:${order.idempotencyKey}`, 86400, transactionId);

      // Publish Order Event Async
      await this.kafkaProducer.send('orders.created', {
        orderId: order.orderId,
        customerId: order.customerId,
        totalAmount,
        transactionId,
        timestamp: new Date().toISOString()
      });

      MetricsCollector.histogram('order_processing_latency_ms', Date.now() - startTime);
      return { success: true, transactionId };
    } catch (err: any) {
      await client.query('ROLLBACK');
      MetricsCollector.increment('order_processing_errors');
      return { success: false, error: err.message };
    } finally {
      client.release();
    }
  }
}

import { createClient, RedisClientType } from 'redis';
import { Logger } from '../utils/logger';

export class RedisClient {
  private client: RedisClientType;
  private isConnected: boolean = false;

  constructor(redisUrl: string) {
    this.client = createClient({ url: redisUrl });
    this.client.on('error', (err) => Logger.error(`Redis Client Error: ${err}`));
    this.client.on('connect', () => {
      this.isConnected = true;
      Logger.info('Redis connection established successfully');
    });
  }

  public async connect(): Promise<void> {
    if (!this.isConnected) {
      await this.client.connect();
    }
  }

  public async get(key: string): Promise<string | null> {
    return await this.client.get(key);
  }

  public async setEx(key: string, seconds: number, value: string): Promise<void> {
    await this.client.setEx(key, seconds, value);
  }

  public async del(key: string): Promise<void> {
    await this.client.del(key);
  }

  public async acquireRedlock(resourceKeys: string[], ttlMs: number): Promise<boolean> {
    const lockVal = Math.random().toString(36).substring(2);
    let acquiredCount = 0;
    for (const key of resourceKeys) {
      const ok = await this.client.set(`lock:${key}`, lockVal, { NX: true, PX: ttlMs });
      if (ok === 'OK') acquiredCount++;
    }
    return acquiredCount >= Math.floor(resourceKeys.length / 2) + 1;
  }
}

-- Database Migration 001: Initial Core Schema

CREATE TABLE IF NOT EXISTS tenants (
    id VARCHAR(36) PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS users (
    id VARCHAR(36) PRIMARY KEY,
    tenant_id VARCHAR(36) REFERENCES tenants(id),
    email VARCHAR(255) UNIQUE NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS inventory (
    sku VARCHAR(64) PRIMARY KEY,
    warehouse_id VARCHAR(36) NOT NULL,
    title VARCHAR(255) NOT NULL,
    stock_quantity INT NOT NULL CHECK (stock_quantity >= 0),
    unit_price NUMERIC(12, 2) NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS orders (
    id VARCHAR(36) PRIMARY KEY,
    customer_id VARCHAR(36) REFERENCES users(id),
    tenant_id VARCHAR(36) REFERENCES tenants(id),
    total_amount NUMERIC(12, 2) NOT NULL,
    status VARCHAR(32) NOT NULL,
    transaction_id VARCHAR(64) UNIQUE NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
) PARTITION BY RANGE (created_at);

CREATE INDEX idx_orders_customer_id ON orders(customer_id);
CREATE INDEX idx_orders_tenant_id ON orders(tenant_id);
CREATE INDEX idx_orders_status ON orders(status);

import { OrderProcessor, OrderPayload } from '../src/services/order_processor';

describe('OrderProcessor Integration Tests', () => {
  let mockDbPool: any;
  let mockRedis: any;
  let mockKafka: any;
  let processor: OrderProcessor;

  beforeEach(() => {
    mockDbPool = {
      connect: jest.fn().mockResolvedValue({
        query: jest.fn().mockImplementation((queryText: string) => {
          if (queryText.includes('FOR UPDATE')) {
            return { rows: [{ stock_quantity: 10 }] };
          }
          return { rows: [] };
        }),
        release: jest.fn()
      })
    };
    mockRedis = { get: jest.fn().mockResolvedValue(null), setEx: jest.fn().mockResolvedValue('OK') };
    mockKafka = { send: jest.fn().mockResolvedValue(true) };
    processor = new OrderProcessor(mockDbPool, mockRedis, mockKafka);
  });

  it('should process valid orders successfully', async () => {
    const payload: OrderPayload = {
      orderId: 'ord_12345',
      customerId: 'usr_999',
      tenantId: 'tenant_enterprise_01',
      items: [{ sku: 'SKU-001', quantity: 2, unitPrice: 49.99, warehouseId: 'wh_us_east' }],
      paymentMethodId: 'pm_card',
      shippingAddress: '123 Enterprise Way',
      idempotencyKey: 'key_idemp_991823'
    };

    const res = await processor.processOrder(payload);
    expect(res.success).toBe(true);
    expect(res.transactionId).toBeDefined();
  });
});
